// 汐见牌局 v0.1.0 · 原创三列式卡牌小游戏
const GAME_ID='shiomi_cards';
const hostWin=(()=>{try{return window.parent&&window.parent.document?window.parent:window}catch(_){return window}})();
const games=hostWin.ShiomiGames||window.ShiomiGames;if(!games)throw new Error('ShiomiGames 未初始化。');

const UNITS=[
 ['tsurumi_fix','鹤见修理工','front',4],['river_patrol','河岸巡灯人','front',5],['market_guard','白鹭护货人','front',6],['night_bouncer','宵待门卫','front',7],['station_shift','站前夜班组','front',8],['port_foreman','东港领班','front',9],
 ['radio_clerk','讯务值班员','support',4],['market_runner','白鹭跑腿人','support',5],['univ_observer','河岸观测员','support',6],['stage_musician','宵待乐师','support',7],['airship_signal','空艇信号员','support',8],['dispatch_officer','调度主任','support',9],
 ['tram_team','电车检修班','machine',4],['warehouse_team','仓库装卸班','machine',5],['boiler_watch','锅炉值守组','machine',6],['rail_crane','铁路起重机','machine',7],['dock_crane','港区吊机','machine',8],['airship_ground','空艇地勤组','machine',9],
];
const SPECIALS=[
 {id:'frost',name:'寒潮',type:'weather',row:'front',description:'双方前列单位本轮战力降为1。'},
 {id:'mist',name:'浓雾',type:'weather',row:'support',description:'双方支援单位本轮战力降为1。'},
 {id:'jam',name:'线路故障',type:'weather',row:'machine',description:'双方机械单位本轮战力降为1。'},
 {id:'clear',name:'天气转晴',type:'clear',description:'清除全部环境影响。'},
];
const ROWS=[['front','前列'],['support','支援'],['machine','机械']];
function cardPool(){return [...UNITS.map(x=>({id:x[0],name:x[1],type:'unit',row:x[2],power:x[3]})),...SPECIALS.map(x=>({...x})),...UNITS.slice(0,8).map(x=>({id:x[0]+'_2',name:x[1],type:'unit',row:x[2],power:x[3]}))];}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function scoreSide(state,side){let total=0;for(const [row] of ROWS){for(const c of state.board[side][row])total+=state.weather.has(row)?1:c.power;}return total;}
function rowScore(state,side,row){return state.board[side][row].reduce((n,c)=>n+(state.weather.has(row)?1:c.power),0);}
function cardLabel(c){return c.type==='unit'?`${c.power}`:c.type==='clear'?'晴':'△';}
function other(side){return side==='player'?'ai':'player';}

const definition={id:GAME_ID,label:'汐见牌局',description:'原创三列式卡牌对局；三局两胜，手牌跨轮保留。',mount(container,api){
 const state={deck:{player:shuffle(cardPool()),ai:shuffle(cardPool())},hand:{player:[],ai:[]},board:{player:{front:[],support:[],machine:[]},ai:{front:[],support:[],machine:[]}},discard:{player:[],ai:[]},weather:new Set(),lives:{player:2,ai:2},passed:{player:false,ai:false},turn:'player',round:1,ended:false,message:'你的回合。',selected:null};
 state.hand.player=state.deck.player.splice(0,10);state.hand.ai=state.deck.ai.splice(0,10);
 container.innerHTML=`<div class="sc"><style>
 .sc{min-height:100%;padding:18px 14px 30px;background:radial-gradient(circle at 48% 20%,#414438 0,#242b2a 36%,#111616 82%);color:#ece7d8;font-family:"Noto Sans CJK SC","Microsoft YaHei",sans-serif}.sc-wrap{width:min(1080px,100%);margin:auto}.sc-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:6px 54px 12px 4px}.sc-head h1{margin:0;font:700 28px/1.1 "Noto Serif CJK SC","Songti SC",serif;letter-spacing:.12em}.sc-sub{color:#aeb5aa;font-size:12px}.sc-scorebox{display:flex;gap:12px}.sc-life{padding:8px 11px;border:1px solid #59605a;border-radius:10px;background:#1b211f}.sc-board{display:grid;gap:7px}.sc-row{display:grid;grid-template-columns:84px 1fr 48px;min-height:88px;border:1px solid #4a514d;border-radius:12px;background:linear-gradient(90deg,rgba(36,44,41,.9),rgba(25,31,30,.92));overflow:hidden}.sc-row.weather{box-shadow:inset 0 0 0 2px rgba(149,175,178,.28)}.sc-rname{display:grid;place-items:center;padding:8px;border-right:1px solid #48504b;color:#c9c4b7;font-weight:650}.sc-cards{display:flex;align-items:center;gap:6px;padding:7px;overflow-x:auto}.sc-rscore{display:grid;place-items:center;border-left:1px solid #48504b;font-size:20px;font-weight:700;color:#e9d3a4}.sc-card{flex:0 0 62px;height:74px;border:1px solid #6c736c;border-radius:8px;background:linear-gradient(#d8d0b8,#b7aa8c);color:#292a25;padding:5px;display:grid;grid-template-rows:1fr auto;box-shadow:0 3px 8px rgba(0,0,0,.22)}.sc-card b{font-size:10px;line-height:1.2}.sc-card span{justify-self:end;font:800 18px/1 Georgia,serif}.sc-hand .sc-card{cursor:pointer;transition:transform .12s,border-color .12s}.sc-hand .sc-card:hover,.sc-hand .sc-card.sel{transform:translateY(-5px);border-color:#e7c479;box-shadow:0 6px 12px rgba(0,0,0,.3),0 0 0 2px rgba(231,196,121,.22)}.sc-hand{margin-top:10px;padding:10px;border:1px solid #4a514d;border-radius:12px;background:#171d1c}.sc-handlist{display:flex;gap:7px;overflow-x:auto;padding:8px 2px 3px}.sc-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:10px 0;flex-wrap:wrap}.sc-msg{color:#d4cec0}.sc button{border:1px solid #70634e;border-radius:9px;background:#685236;color:#fff4df;padding:10px 13px;font:650 13px/1 inherit;cursor:pointer}.sc button.secondary{background:#242a28;border-color:#59605a}.sc button:disabled{opacity:.4;cursor:default}.sc-weather{display:flex;gap:6px;flex-wrap:wrap}.sc-chip{padding:5px 8px;border-radius:999px;background:#303b3a;color:#c8d6d3;font-size:11px}.sc-aihand{height:24px;color:#9aa49f;font-size:12px;text-align:center}.sc-divider{height:1px;background:#535b56;margin:7px 0}.sc-end{padding:30px;text-align:center;border:1px solid #6d6451;border-radius:15px;background:#1c211f}.sc-end h2{font:700 28px/1.2 "Noto Serif CJK SC","Songti SC",serif;margin:0 0 8px}@media(max-width:700px){.sc{padding:10px 7px 24px}.sc-head{display:block}.sc-scorebox{margin-top:8px}.sc-row{grid-template-columns:58px 1fr 38px;min-height:78px}.sc-card{flex-basis:54px;height:66px}.sc-rname{font-size:11px}.sc-rscore{font-size:16px}}
 </style><div class="sc-wrap"><header class="sc-head"><div><h1>汐见牌局</h1><div class="sc-sub">原创三列式卡牌小游戏 · 牌局结果不会自动改写剧情</div></div><div class="sc-scorebox"><div class="sc-life" data-life-player></div><div class="sc-life" data-life-ai></div></div></header><div data-main></div></div></div>`;
 const main=container.querySelector('[data-main]');
 function cardHtml(c,hand=false,i=0){return `<div class="sc-card${hand&&state.selected===i?' sel':''}" ${hand?`data-card="${i}"`:''} title="${esc(c.description||'')}"><b>${esc(c.name)}</b><span>${esc(cardLabel(c))}</span></div>`;}
 function weatherLabel(){return ROWS.filter(([r])=>state.weather.has(r)).map(([,n])=>`<span class="sc-chip">${n}受影响</span>`).join('')||'<span class="sc-chip">环境正常</span>';}
 function render(){container.querySelector('[data-life-player]').textContent=`你：${'●'.repeat(state.lives.player)}${'○'.repeat(2-state.lives.player)}`;container.querySelector('[data-life-ai]').textContent=`对手：${'●'.repeat(state.lives.ai)}${'○'.repeat(2-state.lives.ai)}`;
  if(state.ended){const ps=state.lives.player,as=state.lives.ai;const result=ps===as?'平局':ps>as?'你赢得牌局':'对手赢得牌局';main.innerHTML=`<section class="sc-end"><h2>${result}</h2><p>最终轮次：${state.round}</p><div class="sc-toolbar" style="justify-content:center"><button data-act="send-result">写入剧情输入框</button><button class="secondary" data-act="restart">再来一局</button></div></section>`;return;}
  const boardSide=side=>ROWS.map(([row,name])=>`<div class="sc-row ${state.weather.has(row)?'weather':''}"><div class="sc-rname">${name}</div><div class="sc-cards">${state.board[side][row].map(c=>cardHtml(c)).join('')}</div><div class="sc-rscore">${rowScore(state,side,row)}</div></div>`).join('');
  main.innerHTML=`<div class="sc-aihand">对手手牌 ${state.hand.ai.length} 张 ${state.passed.ai?'· 已停牌':''}</div><div class="sc-board">${boardSide('ai')}<div class="sc-divider"></div>${boardSide('player')}</div><div class="sc-toolbar"><div><strong>第 ${state.round} 轮</strong>　你 ${scoreSide(state,'player')} : ${scoreSide(state,'ai')} 对手</div><div class="sc-weather">${weatherLabel()}</div></div><div class="sc-hand"><div class="sc-toolbar"><span class="sc-msg">${esc(state.message)}</span><div><button data-act="play" ${state.turn!=='player'||state.passed.player||state.selected==null?'disabled':''}>出牌</button> <button class="secondary" data-act="pass" ${state.turn!=='player'||state.passed.player?'disabled':''}>停牌</button></div></div><div class="sc-handlist">${state.hand.player.map((c,i)=>cardHtml(c,true,i)).join('')}</div></div>`;
 }
 function playCard(side,index){const c=state.hand[side][index];if(!c)return false;state.hand[side].splice(index,1);if(c.type==='unit')state.board[side][c.row].push(c);else if(c.type==='weather')state.weather.add(c.row);else if(c.type==='clear')state.weather.clear();state.discard[side].push(c.type==='unit'?null:c);return true;}
 function chooseAi(){const hand=state.hand.ai;if(!hand.length)return {pass:true};const ai=scoreSide(state,'ai'),pl=scoreSide(state,'player');if(state.passed.player&&ai>pl)return {pass:true};if(ai-pl>=7&&hand.length<=state.hand.player.length+1&&Math.random()<.65)return {pass:true};if(hand.length<=2&&ai>=pl&&Math.random()<.7)return {pass:true};
  const candidates=hand.map((c,i)=>({c,i}));for(const row of ['front','support','machine']){const own=rowScore(state,'ai',row),opp=rowScore(state,'player',row);const hit=candidates.find(x=>x.c.type==='weather'&&x.c.row===row);if(hit&&opp-own>=7&&!state.weather.has(row))return {index:hit.i};}
  if(state.weather.size){const clear=candidates.find(x=>x.c.type==='clear');const hurt=ROWS.reduce((n,[r])=>n+(state.weather.has(r)?rowScore(state,'ai',r)-rowScore(state,'player',r):0),0);if(clear&&hurt>4)return {index:clear.i};}
  const units=candidates.filter(x=>x.c.type==='unit').sort((a,b)=>a.c.power-b.c.power);if(units.length){const deficit=Math.max(0,pl-ai+1);const fit=units.find(x=>x.c.power>=deficit);return {index:(fit||units[Math.min(units.length-1,Math.floor(units.length*.55))]).i};}return {index:0};}
 function allPassed(){return state.passed.player&&state.passed.ai;}
 function roundEnd(){const ps=scoreSide(state,'player'),as=scoreSide(state,'ai');if(ps>as)state.lives.ai--;else if(as>ps)state.lives.player--;else{state.lives.player--;state.lives.ai--;}
  for(const side of ['player','ai'])for(const [r] of ROWS){state.discard[side].push(...state.board[side][r]);state.board[side][r]=[];}state.weather.clear();state.passed.player=state.passed.ai=false;state.selected=null;
  if(state.lives.player<=0||state.lives.ai<=0){state.ended=true;render();return;}state.round++;state.turn=ps>=as?'player':'ai';state.message=state.turn==='player'?'新一轮，你先出牌。':'新一轮，对手先出牌。';render();if(state.turn==='ai')setTimeout(aiTurn,550);
 }
 function advance(){if(allPassed()){setTimeout(roundEnd,450);return;}const next=other(state.turn);state.turn=state.passed[next]?state.turn:next;render();if(state.turn==='ai'&&!state.passed.ai)setTimeout(aiTurn,500);}
 function aiTurn(){if(state.ended||state.turn!=='ai')return;const choice=chooseAi();if(choice.pass){state.passed.ai=true;state.message='对手选择停牌。';}else{const c=state.hand.ai[choice.index];playCard('ai',choice.index);state.message=`对手打出「${c.name}」。`;if(!state.hand.ai.length)state.passed.ai=true;}advance();}
 function restart(){state.deck.player=shuffle(cardPool());state.deck.ai=shuffle(cardPool());state.hand.player=state.deck.player.splice(0,10);state.hand.ai=state.deck.ai.splice(0,10);state.board={player:{front:[],support:[],machine:[]},ai:{front:[],support:[],machine:[]}};state.discard={player:[],ai:[]};state.weather.clear();state.lives={player:2,ai:2};state.passed={player:false,ai:false};state.turn='player';state.round=1;state.ended=false;state.message='你的回合。';state.selected=null;render();}
 container.addEventListener('click',e=>{const card=e.target.closest('[data-card]');if(card&&!state.ended&&state.turn==='player'){state.selected=Number(card.dataset.card);render();return;}const act=e.target.closest('button')?.dataset.act;if(act==='play'&&state.turn==='player'&&state.selected!=null){const c=state.hand.player[state.selected];playCard('player',state.selected);state.selected=null;state.message=`你打出「${c.name}」。`;if(!state.hand.player.length)state.passed.player=true;advance();}else if(act==='pass'&&state.turn==='player'){state.passed.player=true;state.message='你选择停牌。';advance();}else if(act==='restart')restart();else if(act==='send-result'){const ps=state.lives.player,as=state.lives.ai;const result=ps===as?'平局':ps>as?'玩家获胜':'对手获胜';api.writeToComposer(`[汐见牌局] 本局结果：${result}。`);}});
 render();return()=>{};
}};
games.register(definition);export default definition;
